import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0055 — Grafo del vault in 3D, con disegni, lavagne e basi come nodi (M18, traccia D)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0055-grafo-3d.md","filePath":"adr/0055-grafo-3d.md"}'),t={name:"adr/0055-grafo-3d.md"};function r(l,e,d,s,c,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0055-—-grafo-del-vault-in-3d-con-disegni-lavagne-e-basi-come-nodi-m18-traccia-d" tabindex="-1">ADR-0055 — Grafo del vault in 3D, con disegni, lavagne e basi come nodi (M18, traccia D) <a class="header-anchor" href="#adr-0055-—-grafo-del-vault-in-3d-con-disegni-lavagne-e-basi-come-nodi-m18-traccia-d" aria-label="Permalink to &quot;ADR-0055 — Grafo del vault in 3D, con disegni, lavagne e basi come nodi (M18, traccia D)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata il 2026-11-15 (decisione dell&#39;owner); implementata e rilasciata con la 1.7.0 (<code>task ci</code> verde il 2026-11-15), con il livello intermedio istanziato aggiunto nella 1.7.1</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.6 (2026-11-15): §2.2.1, §3.4.6, §4.2, Appendice A e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (riga «Graph view globale e locale»: «Canvas 2D (WebGL come riserva)»), §2.4 punto 4 (i link degli elementi di disegni e lavagne «diventano archi del grafo»), §3.4.6 (riga di <code>graph.json</code>), Appendice A (riga «Grafo»: 10.000 nodi a ≥ 30 fps); D-06 (perimetro per-vault), V-02/D-01 (architettura chiusa); ADR-0013 (grafo 2D), ADR-0020 (budget del bundle), ADR-0029 e ADR-0030 (workbench web e core WASM), ADR-0037 e ADR-0045 (registro delle funzioni e parità)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no, è un&#39;aggiunta: lo spec non prevede una vista 3D e non contraddice nulla di ciò che resta del 2D. Da integrare: §2.2.1 (riga della Graph view), Appendice A (la riga «Grafo» vale per il 2D; il 3D ha un inviluppo suo, misurato in <a href="./../qa/graph-3d-benchmark.html"><code>graph-3d-benchmark.md</code></a>), §3.4.6 (le chiavi nuove di <code>graph.json</code>). §2.4 punto 4 diventa vero com&#39;è scritto: prima del lavoro i disegni e le lavagne non comparivano nel grafo. L&#39;elenco puntuale è in «Sezioni dello spec da aggiornare» in fondo</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: vitest <code>geometry3d.test.ts</code>, <code>layoutEngine3d.test.ts</code>, <code>GraphView.3d.test.tsx</code>, <code>lod.test.ts</code>, aggiunte a <code>graph.test.ts</code> e <code>incremental.test.ts</code>; <code>TestBuildDocuments</code> in <code>apps/desktop/internal/graph/graph_test.go</code>; e2e <code>graph-3d.spec.ts</code> sul mock dei binding, in Chromium; a11y in <code>a11y.spec.ts</code>) · workbench web (stessa UI e stesso core in WebAssembly; prove: lo stesso <code>graph-3d.spec.ts</code> sul core WASM nel browser e <code>web/e2e-security/workbench-csp.spec.ts</code>, che gira sull&#39;handler e sulla CSP di produzione: il test del 3D, in origine <code>graph3d-csp.spec.ts</code>, dalla 1.7.1 sta in quel file e prova anche il livello istanziato) · console: non applicabile · cloud: non applicabile, nessuna modifica di API, schema o sync. Registro: voce <code>graph.3d</code> di <code>shared/parity/features.yaml</code> («sì» su desktop e workbench). <strong>Non provato sulla WebView reale del desktop</strong> (vedi «Cosa resta da verificare»)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>ADR-0013 ha scelto per il grafo il Canvas 2D con <code>d3-force</code> in un Web Worker e ha lasciato WebGL come riserva «se in un webview reale i numeri non bastano». Per M18 il proprietario ha chiesto una vista <strong>Grafo 3D</strong> dei link del vault con <code>3d-force-graph</code>, le icone per tipo di documento e un accesso dal ribbon; la decisione sul punto è un interruttore 2D/3D <strong>dentro la vista grafo esistente</strong>. La libreria (<code>3d-force-graph</code>, su <code>three</code>) l&#39;ha scelta il proprietario.</p><p>Il piano prevedeva tre livelli di dettaglio. Prima di costruire, lo spike D0 (un prototipo usa-e-getta, non fuso nel prodotto; le sue misure grezze sono in <a href="./../qa/graph-3d-spike-d0/"><code>docs/qa/graph-3d-spike-d0/</code></a>) ha provato la libreria sulle build desktop e web, con la CSP di produzione, a 3.000 nodi su Apple M4. Esito: sì, con tre condizioni, che questo ADR assume come vincoli:</p><ol><li>i link di serie costano un oggetto per link (19 fps in orbita a 3.000 nodi): vanno in <strong>un solo <code>LineSegments</code></strong>;</li><li>il layout della libreria gira sul thread principale: a 5.000 nodi si assestava in 23 s a 13,8 fps. Il layout deve stare in un <strong>worker</strong>;</li><li>un tetto di <strong>5.000 nodi</strong>.</li></ol><p>Lo spike ha anche trovato due problemi di sicurezza e di peso. <code>ngraph.forcelayout</code> e <code>ngraph.graph</code>, dipendenze della libreria, costruiscono codice con <code>new Function</code>, che la CSP del client e del workbench (<code>script-src &#39;self&#39; &#39;wasm-unsafe-eval&#39;</code>) vieta; e <code>three-render-objects</code> importa <code>three/webgpu</code>, un secondo renderer che nessuno usa ma che finirebbe nel bundle.</p><p>Un&#39;altra lacuna, indipendente dal 3D, è emersa mentre si decideva cosa mostrare: lo spec dice (§2.4 punto 4) che i link dei disegni e delle lavagne diventano archi del grafo, ma <code>graph.Build</code> conosceva solo note e allegati, e le sole note erano sorgenti di link.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="una-vista-due-modalita" tabindex="-1">Una vista, due modalità <a class="header-anchor" href="#una-vista-due-modalita" aria-label="Permalink to &quot;Una vista, due modalità&quot;">​</a></h3><ol><li><strong>Interruttore nella barra del grafo</strong> (pulsante con icona <code>cube</code>, <code>data-testid=&quot;graph-mode&quot;</code>, <code>aria-pressed</code>), non una vista separata: il guscio (<code>GraphView.tsx</code>: filtri, gruppi, timelapse, stato, grafo locale) è uno solo; <code>Graph2D.tsx</code> e <code>three/Graph3D.tsx</code> sono due superfici con le stesse proprietà (<code>surface.ts</code>).</li><li><strong>La modalità è per dispositivo</strong>: <code>localStorage</code>, chiave <code>clarae.graph.mode</code> (<code>&#39;2d&#39;</code> o <code>&#39;3d&#39;</code>, <code>graph/mode.ts</code>), non <code>.clarae/graph.json</code>, che viaggia con la sincronizzazione: dipende dalla GPU e dallo schermo di quel dispositivo (come per la mini-mappa, ADR-0053). Se <code>localStorage</code> non è disponibile la scelta vale per la sessione.</li><li><strong>Le altre opzioni del 3D sono per vault</strong>, in <code>.clarae/graph.json</code> (<code>graph/settings.ts</code>): <code>curvedLinks</code> (link reciproci curvi, default vero), <code>showLegend</code> (default vero), <code>maxNodes3d</code> (500…5.000, default 5.000, passo 500 nel pannello) e <code>showDocuments</code> (default vero, vale anche per il 2D).</li><li><strong>Comandi</strong> <code>graph:open-3d</code> («Apri vista grafo in 3D»: imposta la modalità 3D e apre il grafo globale; ha anche un pulsante nel ribbon, icona <code>cube</code>) e <code>graph:toggle-3d</code> («Grafo: passa tra 2D e 3D»), entrambi senza scorciatoia di default e abilitati con un vault aperto. Voce di parità <code>graph.3d</code> in <code>shared/parity/features.yaml</code>.</li></ol><h3 id="libreria-e-layout" tabindex="-1">Libreria e layout <a class="header-anchor" href="#libreria-e-layout" aria-label="Permalink to &quot;Libreria e layout&quot;">​</a></h3><ol start="5"><li><strong>Dipendenze pinnate</strong> in <code>packages/workbench/package.json</code>: <code>3d-force-graph</code> 1.80.2, <code>three</code> 0.187.0, <code>d3-force-3d</code> 3.0.6, <code>@types/three</code> 0.187.0 (sviluppo).</li><li><strong>Le tre condizioni dello spike:</strong><ul><li><strong>Link in un unico <code>LineSegments</code></strong> (<code>geometry3d.ts</code>: <code>planLinks</code> pianifica il buffer, <code>writeLinks</code> lo scrive a ogni posizione nuova; <code>three/scene.ts</code>). I link reciproci (A→B e B→A) sono due archi di 6 segmenti ciascuno, se <code>curvedLinks</code> è acceso.</li><li><strong>Layout nel worker già esistente</strong> (<code>layout.worker.ts</code>, stesso file del 2D). <code>layoutHost.startLayout(…, dims)</code> con <code>dims: 3</code> fa costruire <code>LayoutEngine3D</code> (<code>layoutEngine3d.ts</code>, su <code>d3-force-3d</code>); i messaggi <code>fix</code> e <code>release</code> tengono fermi i nodi trascinati. La simulazione interna di <code>3d-force-graph</code> resta senza forze e non fa tick: le posizioni vengono dal worker. Oltre 1.000 nodi (<code>LARGE</code>) le forze sono più leggere: repulsione approssimata di più (<code>theta</code> 1,5 invece di 0,9), a raggio limitato (250 invece di 1.000), raffreddamento più rapido.</li><li><strong>Tetto di 5.000 nodi:</strong> il guscio passa <code>maxNodes</code> (<code>maxNodes3d</code>) a <code>graph.Build</code> solo in 3D; <code>Build</code> tiene i più connessi, la risposta è <code>truncated</code> e la riga di stato dice «Mostrati N nodi su M (i più collegati)» (<code>graph.truncated</code>). In 2D il tetto resta quello di ADR-0013.</li></ul></li></ol><h3 id="livelli-di-dettaglio-tre-due-nella-1-7-0-tre-dalla-1-7-1" tabindex="-1">Livelli di dettaglio: tre (due nella 1.7.0, tre dalla 1.7.1) <a class="header-anchor" href="#livelli-di-dettaglio-tre-due-nella-1-7-0-tre-dalla-1-7-1" aria-label="Permalink to &quot;Livelli di dettaglio: tre (due nella 1.7.0, tre dalla 1.7.1)&quot;">​</a></h3><ol start="7"><li><p>Il piano chiedeva sprite con icona, geometrie semplici per tipo e sfere. Lo spike D0 ha misurato che <strong>sprite e sfere costano lo stesso</strong>, perché il costo è una draw call per nodo: a 5.000 nodi su Apple M4 con Metal, 12,9 ms di CPU per frame con gli sprite e 9,3 ms con le sfere, in entrambi i casi 5.001 draw call. Il livello che cambiava le cose era quello a punti (7 draw call a qualunque dimensione, nello spike). Per questo la 1.7.0 è uscita con <strong>due livelli</strong> (sprite fino a 2.000 nodi, punti oltre). Lo spike misurava però le sfere come oggetti separati, una draw call per nodo: non misurava le <strong>geometrie istanziate</strong>, che ne fanno una per forma. La 1.7.1 (M20, sessione S4) le ha misurate, con la regola dell&#39;owner «se non migliora si toglie e si scrive»: migliora, quindi i livelli sono <strong>tre</strong>, scelti dal numero di nodi (<code>lodFor</code>, <code>graph/lod.ts</code>):</p><ul><li><strong>fino a 1.000 nodi</strong> (<code>SPRITE_NODES</code>): uno <strong>sprite</strong> per nodo, con l&#39;icona del tipo, <strong>trascinabile</strong> (lo disegna e lo interroga la libreria);</li><li><strong>da 1.001 a 2.000 nodi</strong> (<code>INSTANCED_NODES</code>): <strong>solidi istanziati</strong>, un <code>InstancedMesh</code> per forma, con il colore (della classe, come per gli sprite) e la scala per istanza. Forme: sfera per note e presentazioni, cubo per i disegni, ottaedro per le lavagne, cilindro per le basi, cono per gli allegati, toro per i tag, icosaedro per le note non ancora create (<code>kindShape</code>). Picking e trascinamento li fa la scena stessa (la libreria non conosce questi oggetti), quindi i nodi restano <strong>trascinabili</strong>; la legenda mostra la forma al posto dell&#39;icona (<code>ShapeGlyph.tsx</code>);</li><li><strong>oltre 2.000 nodi</strong>: un oggetto <code>Points</code> per «aspetto» (colore della classe più icona del tipo), con <strong>picking proprio</strong> (<code>PICK_PX</code> = 12 px) e <strong>senza trascinamento</strong>.</li></ul><p>Con più tipi di documento il livello a punti fa una draw call per aspetto: non misurato su un vault reale.</p><p><strong>Misura</strong> (una o due serie per riga, su una macchina condivisa con carico variabile: ordini di grandezza, non garanzie; tabelle e metodo in <a href="./../qa/graph-3d-benchmark.html"><code>graph-3d-benchmark.md</code></a>). Con un grafo misto di nove tipi di documento (<code>CLARAE_GRAPH3D_KINDS=mixed</code>): su Metal il livello istanziato fa 8 draw call a qualunque dimensione e 0,1 ms di CPU di render per frame, contro 0,9 ms degli sprite a 1.000 nodi e 1,8 ms a 2.000; gli fps non cambiano (60, limitati dal vsync). Su SwiftShader (rasterizzatore software) a 2.000 nodi il livello istanziato fa 11,3 / 27,3 fps contro 9,3 / 18,0 degli sprite (fps in orbita in due serie, la prima con la macchina più carica). <strong>Oltre 2.000 nodi non guadagna sui punti</strong> (stessa CPU) e su software perde, per i triangoli: a 5.000 nodi 7,7 fps contro 24,7. Per questo il livello istanziato <strong>si ferma a 2.000</strong>.</p><p><strong>Costo:</strong> il chunk <code>Graph3D-*.js</code> cresce di 10,6 KiB e <code>layout.worker.js</code> di 0,9 kB; i budget del bundle non cambiano. Il benchmark ha ora <code>CLARAE_GRAPH3D_KINDS=mixed</code> (nove tipi), <code>CLARAE_GRAPH3D_LOD=sprite|instanced|points</code> per forzare il livello (solo nelle build E2E) e colonne per la CPU di render e i triangoli.</p></li><li><p><strong>Icone e colori.</strong> L&#39;icona di ogni tipo è la stessa dell&#39;esploratore dei file (<code>KIND_ICON</code> in <code>embeds/media.ts</code>, ora esportata; <code>graph/kinds.ts</code> aggiunge <code>tag</code> e <code>ghost</code>), disegnata su una <code>CanvasTexture</code> dai path di <code>shell/iconData.ts</code>: nessuna richiesta di rete. Il colore del disco è quello della classe come nel 2D (gruppo di colore, altrimenti tipo di nodo), letto dai token del tema; cambia con il tema. Una legenda mostra il conteggio per tipo (<code>showLegend</code>).</p></li></ol><h3 id="gesti-e-tastiera" tabindex="-1">Gesti e tastiera <a class="header-anchor" href="#gesti-e-tastiera" aria-label="Permalink to &quot;Gesti e tastiera&quot;">​</a></h3><ol start="9"><li>Il primo click su un nodo lo seleziona e porta la camera su di lui; un click sul nodo selezionato, il doppio click o Invio lo aprono; Ctrl/Cmd+click lo apre in una nuova scheda. Trascinare un nodo (livelli a sprite e a solidi, fino a 2.000 nodi) lo lascia <strong>fissato</strong> dove lo si posa, anche dopo un aggiornamento del grafo; «Sblocca i nodi fissati (N)» li libera tutti. Passando il puntatore su un nodo, o selezionandolo, lui e i vicini restano accesi, gli altri si attenuano e i suoi link sono evidenziati. Regole fissate dalla revisione del codice, ciascuna con una prova e2e: anche nel livello a punti un solo click <strong>seleziona</strong> e non apre; un nodo nascosto dal timelapse <strong>non si seleziona né si trascina</strong> (esce anche dal livello che il puntatore interroga); dopo un aggiornamento del grafo la selezione si riferisce al grafo nuovo; scegliere di nuovo il 3D dopo un download fallito del chunk lo riscarica.</li><li><strong>Tastiera</strong> sulla superficie (<code>role=&quot;application&quot;</code>, <code>tabIndex=0</code>, etichetta <code>graph.sceneLabel</code>): frecce ruotano, <code>+</code>/<code>-</code> zoom, <code>0</code> adatta, <code>[</code> e <code>]</code> passano da un nodo all&#39;altro a partire dal più connesso, Invio apre, Esc toglie la selezione.</li><li><strong>Etichette</strong> come testo HTML sopra la scena (<code>textContent</code>, mai markup del vault): per il nodo corrente e i suoi vicini e per i nodi più connessi vicini alla camera, <strong>al massimo 40</strong> alla volta.</li><li>Con <code>prefers-reduced-motion</code> i movimenti di camera diventano istantanei.</li></ol><h3 id="ripiego-risorse" tabindex="-1">Ripiego, risorse <a class="header-anchor" href="#ripiego-risorse" aria-label="Permalink to &quot;Ripiego, risorse&quot;">​</a></h3><ol start="13"><li><strong>Ripiego al 2D con un avviso</strong> (<code>role=&quot;status&quot;</code>, chiavi <code>graph.no3d.*</code>): manca WebGL2; il contesto grafico è andato perso; ci sono già quattro grafi 3D aperti (<code>MAX_3D_SURFACES</code> in <code>webgl.ts</code>, perché una pagina ha pochi contesti WebGL); la vista non si è avviata (il chunk non si carica, la scena solleva un&#39;eccezione). Scegliere di nuovo il 3D ritenta.</li><li><strong>Risorse.</strong> La scena smette di disegnare a riposo, 1,5 s dopo l&#39;ultimo cambiamento (<code>IDLE_MS</code>), e riparte al primo evento. Alla chiusura rilascia tutto e perde di proposito il contesto WebGL (<code>forceContextLoss</code>): senza, i contesti restano fino al garbage collector e pochi grafi chiusi esaurirebbero quelli ammessi (misurato nello spike).</li><li><strong>Chunk lazy.</strong> three.js e <code>3d-force-graph</code> stanno in un chunk a parte (<code>Graph3D-*.js</code>, 791 kB sul desktop e 792 kB sul web, minificato), scaricato alla prima apertura del 3D. <code>layout.worker.js</code> passa a 34,8 kB (contiene ora anche <code>d3-force-3d</code>). Nella 1.7.1 il chunk cresce di 10,6 KiB e il worker di 0,9 kB (punto 7). Budget del bundle (ADR-0020), come stampato dalle build di produzione: desktop <code>initial 1389 kB (limit 2000), total 19225 kB (limit 23000)</code>; web, workbench <code>initial 1950 kB (limit 2500), total 17298 kB (limit 23000)</code>, console <code>initial 697 kB (limit 700)</code> (la console non importa nulla di questo lavoro). Nessun limite è stato alzato.</li></ol><h3 id="sicurezza-e-csp" tabindex="-1">Sicurezza e CSP <a class="header-anchor" href="#sicurezza-e-csp" aria-label="Permalink to &quot;Sicurezza e CSP&quot;">​</a></h3><ol start="16"><li><strong>La CSP non cambia.</strong> Due alias in <code>baseOptions</code> di <code>packages/workbench/build/esbuild.mjs</code>, validi per ogni build: <code>ngraph.forcelayout</code> e <code>ngraph.graph</code> verso <code>build/stubs/ngraph.mjs</code> (lancia se chiamato: la libreria li usa solo con <code>forceEngine(&#39;ngraph&#39;)</code>, che il 3D non sceglie) e <code>three/webgpu</code> verso <code>build/stubs/three-webgpu.mjs</code>. Il plugin <code>noRuntimeCode</code> <strong>fa fallire la build</strong> se un chunk che contiene <code>three</code>, <code>3d-force-graph</code>, <code>three-forcegraph</code>, <code>three-render-objects</code> o <code>d3-force-3d</code> ha <code>eval(</code> o <code>new Function(</code>: provato togliendo l&#39;alias, la build si ferma con il messaggio del plugin. Serve per il prossimo pacchetto che lo faccia, un aggiornamento incluso. Il plugin legge il metafile, che le build delle applicazioni richiedono.</li><li><code>web/e2e-security/workbench-csp.spec.ts</code> (il test del grafo 3D, che nella 1.7.0 stava in <code>graph3d-csp.spec.ts</code>) apre il 3D sull&#39;handler e sulla CSP di produzione, anche al livello istanziato, e verifica che non ci siano violazioni né richieste fuori origine.</li></ol><h3 id="anche-nel-2d-disegni-lavagne-e-basi-come-nodi" tabindex="-1">Anche nel 2D: disegni, lavagne e basi come nodi <a class="header-anchor" href="#anche-nel-2d-disegni-lavagne-e-basi-come-nodi" aria-label="Permalink to &quot;Anche nel 2D: disegni, lavagne e basi come nodi&quot;">​</a></h3><ol start="18"><li><strong><code>graph.Build</code></strong> (<code>apps/desktop/internal/graph/graph.go</code>) dà nodi di tipo <code>drawing</code>, <code>canvas</code> e <code>base</code> (file <code>.excalidraw</code>, <code>.canvas</code>, <code>.base</code>, letti da <code>files.kind</code>). <strong>Disegni e lavagne sono anche sorgenti di link</strong> (i link dei loro elementi, già indicizzati: §2.4 punto 4); una base è solo destinazione, perché non ha link indicizzati. I <strong>tag restano solo delle note</strong>: un filtro per tag nasconde questi nodi, come gli allegati. Una presentazione Marp (<code>.marp</code>) è una nota.</li><li><strong>Opzione <code>ShowDocuments</code></strong> in <code>graph.Options</code>: il valore zero (falso) dà il risultato di prima per ogni chiamante esistente; l&#39;interfaccia la accende per default (casella «Disegni, lavagne e basi» nei filtri, <code>showDocuments</code> in <code>graph.json</code>). Il grafo locale si può centrare anche su un disegno, una lavagna o una presentazione (<code>canCenterGraph</code>; il comando <code>graph:open-local</code> è abilitato per <code>.md</code>, <code>.marp</code>, <code>.excalidraw</code> e <code>.canvas</code>).</li><li><strong>Rapporto con l&#39;NFR del grafo</strong> (10.000 nodi a ≥ 30 fps, M6/ADR-0013): vale per il 2D e non cambia. <strong>Il 3D non lo eredita</strong> e dichiara un inviluppo proprio, misurato: 5.000 nodi come tetto, 60 fps in orbita su una GPU Apple M4 (Metal) e da 19 a 29 fps in orbita con un rasterizzatore software (SwiftShader) (misure della 1.7.0, con due livelli; per il livello istanziato della 1.7.1 vedi il punto 7; tabelle in <a href="./../qa/graph-3d-benchmark.html"><code>graph-3d-benchmark.md</code></a>).</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Grafo 3D come vista separata</strong> (tab e comando propri) — scartata: due viste dello stesso dato duplicherebbero filtri, gruppi, timelapse, stato e grafo locale, o li lascerebbero diversi. Con l&#39;interruttore il guscio è uno solo e la scelta è un pulsante.</li><li><strong>Renderer proprio su <code>three</code>, senza <code>3d-force-graph</code></strong> — scartata: la libreria è la scelta del proprietario e dà orbita, picking e trascinamento già fatti; di suo si sostituiscono solo le tre parti che lo spike ha trovato costose (link, layout, tetto). Il prezzo è un pacchetto in più da tenere d&#39;occhio negli aggiornamenti (punto 16).</li><li><strong>Lasciare il layout alla libreria</strong> — scartata: gira sul thread principale e a 5.000 nodi si assestava in 23 s a 13,8 fps (spike). Il layout nel worker riusa il file e il canale del 2D.</li><li><strong>Tre livelli di dettaglio</strong> (sprite, geometrie semplici, sfere) — <strong>scartata nella 1.7.0, scelta nella 1.7.1.</strong> Scartata perché lo spike misurava sprite e sfere come oggetti separati e costavano lo stesso (una draw call per nodo): un livello in più sarebbe stato codice senza effetto misurato. Ripresa con la geometria istanziata (un <code>InstancedMesh</code> per forma, 8 draw call a qualunque dimensione su un grafo misto) e misurata prima di tenerla: 0,1 ms di CPU per frame contro 0,9 e 1,8 ms degli sprite a 1.000 e 2.000 nodi su Metal, e più fps su software a 2.000 nodi (punto 7). Le sfere come oggetti separati restano scartate.</li><li><strong>Il livello istanziato anche oltre 2.000 nodi</strong> — scartata: oltre non guadagna sui punti (stessa CPU) e su un rasterizzatore software perde (7,7 contro 24,7 fps a 5.000 nodi, per i triangoli).</li><li><strong>Alzare il tetto a 10.000 nodi</strong> — scartata: oltre 5.000 nodi non c&#39;è una misura e il livello a punti ha ancora una draw call per aspetto; il 2D resta la vista per i grafi grandi (e a 10.000 nodi mantiene il suo NFR). Il tetto è una costante e un&#39;impostazione per vault (<code>maxNodes3d</code>): si alza quando ci sono misure su una WebView reale e su hardware più lento.</li><li><strong>Permettere <code>unsafe-eval</code> nella CSP</strong> — scartata: l&#39;architettura è chiusa (V-02/D-01) e la CSP del workbench web e del client è un requisito (§3.7); si tolgono invece le fonti di <code>new Function</code> con un alias e si fa fallire la build se ne compaiono altre.</li><li><strong>Modalità 2D/3D in <code>.clarae/graph.json</code></strong> — scartata: il file si sincronizza e porterebbe la scelta di un dispositivo con una GPU buona su uno senza.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Il 3D si usa dall&#39;interruttore, dai due comandi e dal ribbon; nessun cambio per chi non lo apre, tranne i nodi nuovi (disegni, lavagne, basi), che il 2D mostra per default (si tolgono dai filtri).</li><li>Il chunk di 791 kB si scarica solo alla prima apertura del 3D; il caricamento iniziale non cambia (budget invariati, nessun limite alzato).</li><li>Nuove dipendenze da tenere: <code>three</code>, <code>3d-force-graph</code>, <code>d3-force-3d</code>. Ogni aggiornamento passa dal plugin <code>noRuntimeCode</code> (la build si ferma se un chunk costruisce codice a runtime) e dalle prove sotto; i due alias dipendono da come la libreria importa <code>ngraph.*</code> e <code>three/webgpu</code>.</li><li>Fino a 2.000 nodi i nodi si trascinano (sprite e solidi); oltre, nel livello a punti, no, e con più tipi di documento il livello a punti ha una draw call per aspetto.</li><li>Il livello istanziato ha un picking e un trascinamento propri della scena (non quelli della libreria): sono codice in più da tenere sotto prova (<code>graph-3d.spec.ts</code>, <code>lod.test.ts</code>).</li><li>Il tetto di 5.000 nodi significa che un vault più grande mostra in 3D solo i più connessi (con la riga di stato che lo dice); gli altri si vedono in 2D.</li><li>Accessibilità: la superficie ha etichetta, focus e comandi da tastiera, ma non ha un equivalente testuale del grafo (come il 2D, <a href="./../qa/a11y-desktop.html"><code>a11y-desktop.md</code></a>); il 3D non è la sola via per arrivare a una nota.</li><li>Un vault senza WebGL2 (o con il contesto perso) vede il 2D con un avviso: nessuna funzione manca.</li></ul><h3 id="cosa-resta-da-verificare" tabindex="-1">Cosa resta da verificare <a class="header-anchor" href="#cosa-resta-da-verificare" aria-label="Permalink to &quot;Cosa resta da verificare&quot;">​</a></h3><ul><li><strong>Nessuna prova nell&#39;applicazione desktop reale.</strong> Le prove automatiche girano in Chromium (con i binding simulati e sul core WASM). La WebView del desktop è WKWebView su macOS, WebView2 su Windows, WebKitGTK su Linux: prestazioni, WebGL2 e rilascio del contesto lì non sono stati misurati. Serve una verifica manuale con <code>task run-desktop</code> prima del rilascio.</li><li><strong>GPU integrate, Windows e Linux</strong> non misurati. <strong>Vault reali</strong> non misurati: solo un grafo sintetico di soli nodi «nota», quindi con un solo aspetto.</li><li>Le misure sono una o due serie per riga, su una macchina non isolata e con carico variabile (metodo e numeri in <a href="./../qa/graph-3d-benchmark.html"><code>graph-3d-benchmark.md</code></a>). <strong>Il livello istanziato non è stato visto sulla WebView reale</strong> (forme, legenda, trascinamento), né i livelli sono stati misurati su un vault reale: la verifica manuale è nel runbook <a href="./../qa/verifica-manuale-1.7.html"><code>verifica-manuale-1.7.md</code></a>.</li></ul><h3 id="sezioni-dello-spec-recepite-in-specifications-md-v1-6-2026-11-15" tabindex="-1">Sezioni dello spec (recepite in <code>Specifications.md</code> v1.6, 2026-11-15) <a class="header-anchor" href="#sezioni-dello-spec-recepite-in-specifications-md-v1-6-2026-11-15" aria-label="Permalink to &quot;Sezioni dello spec (recepite in `Specifications.md` v1.6, 2026-11-15)&quot;">​</a></h3><ul><li><strong>§2.2.1</strong>, riga «Graph view globale e locale»: aggiungere la vista 3D (<code>3d-force-graph</code>, interruttore nella vista, modalità per dispositivo, tre livelli di dettaglio, tetto di 5.000 nodi, ripiego al 2D) e i nodi di disegni, lavagne e basi (<code>ShowDocuments</code>); le impostazioni in <code>graph.json</code>.</li><li><strong>Appendice A</strong>, riga «Grafo»: l&#39;NFR dei 10.000 nodi a ≥ 30 fps vale per il 2D; per il 3D rimandare a <code>docs/qa/graph-3d-benchmark.md</code>.</li><li><strong>§3.4.6</strong>, riga di <code>graph.json</code>: chiavi <code>showDocuments</code>, <code>curvedLinks</code>, <code>showLegend</code>, <code>maxNodes3d</code>; la modalità 2D/3D non è lì (è per dispositivo).</li><li><strong>§2.4 punto 4:</strong> nessun cambio di testo; il codice ora lo rispetta (disegni e lavagne come nodi e sorgenti di link, basi solo come destinazione).</li><li><strong>§4.2</strong> (albero <code>graph/</code> del frontend): «rendering grafo (Canvas 2D) + worker layout» diventa «Canvas 2D e scena 3D (<code>three/</code>, chunk lazy) + worker di layout in 2D e 3D».</li><li><strong>Appendice C.4:</strong> riga di ADR-0055.</li></ul>',31)])])}const h=o(t,[["render",r]]);export{g as __pageData,h as default};
